{"path":"/root/solve_spreadsheet.py","content":"import os
import re
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

INPUT = '/root/data/workbook.xlsx'
OUTPUT = '/root/output/result.xlsx'

os.makedirs('/root/output', exist_ok=True)

# Load formulas workbook, not data_only, per instruction.
wb = load_workbook(INPUT)
ws = wb['Task']
ds = wb['Data']

print('Workbook loaded:', INPUT)
print('Sheets:', wb.sheetnames)

# Helpers
blocks = [(12, 17), (19, 24), (26, 31)]
task_year_cols = list(range(8, 13))  # H:L

def norm(v):
    if v is None:
        return None
    if isinstance(v, float) and v.is_integer():
        return int(v)
    return v

def display_row(sheet, row, min_col, max_col):
    vals = []
    for c in range(min_col, max_col + 1):
        vals.append(f'{get_column_letter(c)}{row}={sheet.cell(row, c).value!r}')
    return ' | '.join(vals)

def is_year_like(v):
    if v is None:
        return False
    if isinstance(v, int):
        return 1900 <= v <= 2100
    if isinstance(v, float):
        return v.is_integer() and 1900 <= int(v) <= 2100
    s = str(v).strip()
    return bool(re.fullmatch(r'(19|20)\d{2}', s))

def year_key(v):
    if v is None:
        return None
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        if int(v) == v:
            return str(int(v))
        return str(v)
    return str(v).strip()

print('\n=== Task! row 10 year headers H:L ===')
task_years = []
for c in task_year_cols:
    v = ws.cell(10, c).value
    task_years.append(v)
    print(f'{get_column_letter(c)}10 = {v!r}')
print('Task year keys:', [year_key(v) for v in task_years])

print('\n=== Task! column D series codes in target blocks ===')
task_codes_by_row = {}
for start, end in blocks:
    print(f'Rows {start}:{end}')
    for r in range(start, end + 1):
        v = ws.cell(r, 4).value
        task_codes_by_row[r] = v
        context = ' | '.join(f'{get_column_letter(c)}={ws.cell(r,c).value!r}' for c in range(1, 6))
        print(f'  row {r}: D{r}={v!r}; context {context}')

print('\n=== Task! labels/structure rows 35:50, columns A:G ===')
for r in range(35, 51):
    print(f'Row {r}: ' + display_row(ws, r, 1, 7))

print('\n=== Additional Task! labels around metric blocks, columns A:G rows 10:31 ===')
for r in list(range(10, 18)) + list(range(19, 25)) + list(range(26, 32)):
    print(f'Row {r}: ' + display_row(ws, r, 1, 7))

print('\n=== Data! rows 21:38 used to infer table structure ===')
# Print a broad but bounded range around the table.
max_col_to_print = max(ds.max_column, 15)
for r in range(21, 39):
    nonempty = [c for c in range(1, ds.max_column + 1) if ds.cell(r, c).value is not None]
    if nonempty:
        minc = max(1, min(nonempty) - 1)
        maxc = min(ds.max_column, max(nonempty) + 1)
    else:
        minc, maxc = 1, min(ds.max_column, 15)
    print(f'Row {r}: ' + display_row(ds, r, minc, maxc))

# Determine Data layout.
task_year_keys = {year_key(v) for v in task_years if v is not None}
# Header row: row in 21:38 with the most Task-year matches and/or year-like values.
best_header = None
best_score = (-1, -1)
for r in range(21, 39):
    matches = 0
    yearlikes = 0
    for c in range(1, ds.max_column + 1):
        v = ds.cell(r, c).value
        if year_key(v) in task_year_keys:
            matches += 1
        if is_year_like(v):
            yearlikes += 1
    score = (matches, yearlikes)
    print(f'Data header candidate row {r}: task-year matches={matches}, year-like cells={yearlikes}')
    if score > best_score:
        best_score = score
        best_header = r
if best_header is None or best_score[0] == 0:
    raise RuntimeError('Could not identify Data header row with Task years in rows 21:38')
header_row = best_header

# Year columns: columns in header_row matching Task years. Use min/max over matching columns.
year_cols = [c for c in range(1, ds.max_column + 1) if year_key(ds.cell(header_row, c).value) in task_year_keys]
if not year_cols:
    raise RuntimeError('Could not identify year columns on Data header row')
first_year_col, last_year_col = min(year_cols), max(year_cols)

# Data rows: rows below header through 38 that have values in the detected year area.
candidate_data_rows = []
for r in range(header_row + 1, 39):
    if any(ds.cell(r, c).value is not None for c in range(first_year_col, last_year_col + 1)):
        candidate_data_rows.append(r)
if not candidate_data_rows:
    raise RuntimeError('Could not identify Data table body rows below header')
first_data_row, last_data_row = min(candidate_data_rows), max(candidate_data_rows)

# Series-code column: body column with the most matches to Task codes. Prefer columns left of first year col.
task_code_keys = {str(v).strip() for v in task_codes_by_row.values() if v not in (None, '')}
if len(task_code_keys) < 18:
    missing = [r for r, v in task_codes_by_row.items() if v in (None, '')]
    raise RuntimeError(f'Task series code cells must all be non-empty. Missing rows: {missing}')
code_scores = []
for c in range(1, ds.max_column + 1):
    matches = 0
    nonempty = 0
    for r in range(first_data_row, last_data_row + 1):
        v = ds.cell(r, c).value
        if v not in (None, ''):
            nonempty += 1
            if str(v).strip() in task_code_keys:
                matches += 1
    left_bonus = 1 if c < first_year_col else 0
    code_scores.append((matches, left_bonus, nonempty, c))
code_scores.sort(reverse=True)
best_matches, _, best_nonempty, code_col = code_scores[0]
print('\nSeries-code column candidates (top 8):')
for matches, left_bonus, nonempty, c in code_scores[:8]:
    print(f'  {get_column_letter(c)}: matches={matches}, nonempty_body={nonempty}, left_of_years={bool(left_bonus)}')
if best_matches == 0:
    raise RuntimeError('Could not identify Data series-code column matching Task column D codes')

# Confirm every needed Task code exists in Data code column.
data_codes = {str(ds.cell(r, code_col).value).strip(): r for r in range(first_data_row, last_data_row + 1) if ds.cell(r, code_col).value not in (None, '')}
missing_codes = sorted(task_code_keys - set(data_codes))
if missing_codes:
    raise RuntimeError(f'Task series codes not found in Data!{get_column_letter(code_col)}{first_data_row}:{get_column_letter(code_col)}{last_data_row}: {missing_codes}')

print('\n=== Inferred Data layout ===')
print(f'Header row with years: Data!{header_row}')
print(f'Year header range: Data!${get_column_letter(first_year_col)}${header_row}:${get_column_letter(last_year_col)}${header_row}')
print(f'Series-code column: Data!${get_column_letter(code_col)}${first_data_row}:${get_column_letter(code_col)}${last_data_row}')
print(f'Full rectangular data range: Data!${get_column_letter(first_year_col)}${first_data_row}:${get_column_letter(last_year_col)}${last_data_row}')
print('Data years detected:', [(get_column_letter(c), ds.cell(header_row, c).value) for c in range(first_year_col, last_year_col + 1)])

# Verify metric block labels.
print('\n=== Metric block label verification from Task columns A:G ===')
for start, end in blocks:
    nearby = []
    for r in range(max(1, start - 2), end + 1):
        row_vals = [ws.cell(r, c).value for c in range(1, 8) if ws.cell(r, c).value not in (None, '')]
        if row_vals:
            nearby.append((r, row_vals))
    print(f'Block rows {start}:{end}:')
    for r, vals in nearby:
        print(f'  row {r}: {vals!r}')

# Absolute ranges for formulas.
data_range = f"Data!${get_column_letter(first_year_col)}${first_data_row}:${get_column_letter(last_year_col)}${last_data_row}"
code_range = f"Data!${get_column_letter(code_col)}${first_data_row}:${get_column_letter(code_col)}${last_data_row}"
year_range = f"Data!${get_column_letter(first_year_col)}${header_row}:${get_column_letter(last_year_col)}${header_row}"

# Step 1: lookup formulas.
print('\n=== Writing Step 1 INDEX/MATCH formulas ===')
for start, end in blocks:
    for r in range(start, end + 1):
        if ws.cell(r, 4).value in (None, ''):
            raise RuntimeError(f'Missing Task series code in D{r}')
        for c in task_year_cols:
            col_letter = get_column_letter(c)
            formula = f'=INDEX({data_range},MATCH($D{r},{code_range},0),MATCH({col_letter}$10,{year_range},0))'
            ws.cell(r, c).value = formula
            print(f'{col_letter}{r} <- {formula}')

# Step 2: net budget buffer H35:L40.
print('\n=== Writing Step 2 net budget buffer formulas H35:L40 ===')
for out_row in range(35, 41):
    offset = out_row - 35
    committed_row = 12 + offset
    operating_row = 19 + offset
    budget_row = 26 + offset
    for c in task_year_cols:
        col = get_column_letter(c)
        formula = f'=({col}{committed_row}-{col}{operating_row})/{col}{budget_row}*100'
        ws.cell(out_row, c).value = formula
        print(f'{col}{out_row} <- {formula}')

# Step 2 continued: summary stats H42:L47. Match labels if possible.
print('\n=== Summary-stat labels rows 42:47, columns A:G ===')
label_text_by_row = {}
for r in range(42, 48):
    vals = [str(ws.cell(r, c).value).strip() for c in range(1, 8) if ws.cell(r, c).value not in (None, '')]
    label = ' '.join(vals).lower()
    label_text_by_row[r] = label
    print(f'Row {r} label text: {label!r}')

def stat_formula_for_label(label, col):
    rng = f'{col}35:{col}40'
    l = label.lower()
    # Check percentile/quartile before generic min/max/mean terms where relevant.
    if '25' in l or '0.25' in l or 'first quartile' in l or 'lower quartile' in l or 'q1' in l:
        return f'=PERCENTILE({rng},0.25)'
    if '75' in l or '0.75' in l or 'third quartile' in l or 'upper quartile' in l or 'q3' in l:
        return f'=PERCENTILE({rng},0.75)'
    if 'median' in l:
        return f'=MEDIAN({rng})'
    if 'average' in l or 'mean' in l:
        return f'=AVERAGE({rng})'
    if 'minimum' in l or re.search(r'\bmin\b', l):
        return f'=MIN({rng})'
    if 'maximum' in l or re.search(r'\bmax\b', l):
        return f'=MAX({rng})'
    return None

default_stats = {
    42: lambda col: f'=MIN({col}35:{col}40)',
    43: lambda col: f'=MAX({col}35:{col}40)',
    44: lambda col: f'=MEDIAN({col}35:{col}40)',
    45: lambda col: f'=AVERAGE({col}35:{col}40)',
    46: lambda col: f'=PERCENTILE({col}35:{col}40,0.25)',
    47: lambda col: f'=PERCENTILE({col}35:{col}40,0.75)',
}
print('\n=== Writing summary-stat formulas H42:L47 ===')
for r in range(42, 48):
    for c in task_year_cols:
        col = get_column_letter(c)
        formula = stat_formula_for_label(label_text_by_row.get(r, ''), col) or default_stats[r](col)
        ws.cell(r, c).value = formula
        print(f'{col}{r} <- {formula}')

# Step 3: weighted mean H50:L50.
print('\n=== Writing Step 3 weighted mean formulas H50:L50 ===')
for c in task_year_cols:
    col = get_column_letter(c)
    formula = f'=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)'
    ws.cell(50, c).value = formula
    print(f'{col}50 <- {formula}')

# Verify all target cells have formulas before saving.
target_cells = []
for start, end in blocks:
    for r in range(start, end + 1):
        for c in task_year_cols:
            target_cells.append((r, c))
for r in list(range(35, 41)) + list(range(42, 48)) + [50]:
    for c in task_year_cols:
        target_cells.append((r, c))
missing_formula_cells = []
for r, c in target_cells:
    val = ws.cell(r, c).value
    if not (isinstance(val, str) and val.startswith('=')):
        missing_formula_cells.append(f'{get_column_letter(c)}{r}={val!r}')
if missing_formula_cells:
    raise RuntimeError('Some target cells do not contain formulas: ' + ', '.join(missing_formula_cells))
print(f'\nVerified in-memory formulas in all {len(target_cells)} target cells before saving.')

wb.save(OUTPUT)
print('Saved workbook:', OUTPUT)

# Reload and print sample formulas and all target checks after save.
wb2 = load_workbook(OUTPUT, data_only=False)
ws2 = wb2['Task']
print('\n=== Reloaded formula samples ===')
for addr in ['H12', 'L17', 'H35', 'L40', 'H42', 'H47', 'H50', 'L50']:
    print(f'{addr} = {ws2[addr].value!r}')

post_missing = []
for r, c in target_cells:
    val = ws2.cell(r, c).value
    if not (isinstance(val, str) and val.startswith('=')):
        post_missing.append(f'{get_column_letter(c)}{r}={val!r}')
if post_missing:
    raise RuntimeError('After reload, some target cells do not contain formulas: ' + ', '.join(post_missing))
print(f'After reload, verified every target cell contains a formula: {len(target_cells)} cells.')

# Print formulas in requested representative cells specifically.
print('\nRequested sample cells:')
for addr in ['H12', 'H35', 'H42', 'H50']:
    print(f'{addr}: {ws2[addr].value}')
